INSERT INTO `hotels` VALUES (1,'16 P. Hàng Da, phường Hoàn Kiếm, Hà Nội',9.1125,'2026-05-08 09:49:07.100351','Loud Luxury Hotel Hà Nội','ACTIVE','Khách sạn tọa lạc trong khu vực nội đô hoặc gần các trục đường chính, giúp du khách dễ dàng kết nối đến nhiều địa điểm quan trọng trong thành phố. Mặc dù không gần biển, nhưng khách sạn lại nổi bật với không gian yên tĩnh, sạch sẽ và mức giá hợp lý. Các phòng được thiết kế tối giản nhưng tinh tế, đảm bảo đầy đủ tiện nghi phục vụ nhu cầu nghỉ ngơi và làm việc. Ngoài ra, khách sạn còn có nhà hàng phục vụ ăn sáng, phòng hội nghị nhỏ và dịch vụ giặt ủi, phù hợp cho khách công tác dài ngày hoặc du lịch tiết kiệm.',0,'2026-06-14 22:31:16.915556',2),(2,'28 Trần Phú, phường Nha Trang, Khánh Hòa',9.649999999999999,'2026-05-08 10:06:01.645722','Loud Grand Hotel Khánh Hòa','ACTIVE','Khách sạn tọa lạc ngay khu vực ven biển, chỉ mất vài phút đi bộ để ra đến bãi cát trắng và làn nước trong xanh. Đây là lựa chọn lý tưởng cho những du khách muốn tận hưởng trọn vẹn không khí biển trong lành, thư giãn cùng tiếng sóng vỗ và gió biển mát rượi. Các phòng nghỉ được thiết kế hiện đại, nhiều phòng có cửa sổ lớn hoặc ban công hướng trực tiếp ra biển, giúp du khách dễ dàng ngắm bình minh và hoàng hôn tuyệt đẹp. Ngoài ra, khách sạn còn cung cấp các tiện ích như hồ bơi ngoài trời, nhà hàng hải sản, quầy bar ven biển và dịch vụ tour tham quan đảo, mang đến trải nghiệm nghỉ dưỡng trọn vẹn và thoải mái.',0,'2026-06-06 17:37:05.370155',3),(3,'36 Bạch Đằng, phường Hải Châu, Đà Nẵng',9.6,'2026-05-08 10:17:52.292539','Loud Luxury Hotel Đà Nẵng','ACTIVE','Khách sạn tọa lạc ngay khu vực ven biển, chỉ mất vài phút đi bộ để ra đến bãi cát trắng và làn nước trong xanh. Đây là lựa chọn lý tưởng cho những du khách muốn tận hưởng trọn vẹn không khí biển trong lành, thư giãn cùng tiếng sóng vỗ và gió biển mát rượi. Các phòng nghỉ được thiết kế hiện đại, nhiều phòng có cửa sổ lớn hoặc ban công hướng trực tiếp ra biển, giúp du khách dễ dàng ngắm bình minh và hoàng hôn