INSERT INTO `room_types` VALUES (1,60,1,'KING',2,'2026-05-08 14:14:03.000000','Phòng Suite rộng 60m², được trang bị 1 giường King cao cấp, phù hợp cho 2 khách. Không gian sang trọng, rộng rãi với đầy đủ tiện nghi hiện đại, mang đến trải nghiệm nghỉ dưỡng thoải mái và riêng tư.',0,1000000,'Suite Room','2026-06-14 14:59:01.945939',1),(2,50,2,'QUEEN',4,'2026-05-08 14:14:03.000000','Phòng Family rộng 50m², được bố trí 2 giường Queen rộng rãi, phù hợp cho tối đa 4 khách. Không gian ấm cúng và tiện nghi, lý tưởng cho gia đình hoặc nhóm bạn muốn tận hưởng kỳ nghỉ thoải mái cùng nhau.',0,1800000,'Family Room','2026-05-19 19:45:16.223884',1),(3,35,1,'QUEEN',2,'2026-05-08 14:14:03.000000','Phòng Deluxe rộng 35m², được trang bị 1 giường Queen cao cấp, phù hợp cho 2 khách. Không gian sang trọng, rộng rãi với đầy đủ tiện nghi hiện đại, mang đến trải nghiệm nghỉ dưỡng thoải mái và riêng tư.',0,1200000,'Deluxe Room','2026-06-14 11:33:55.370827',1),(4,30,2,'SINGLE',2,'2026-05-08 14:14:03.000000','Phòng Twin rộng 30m², được trang bị 2 giường đơn phù hợp cho 2 khách. Không gian sang trọng, rộng rãi với đầy đủ tiện nghi hiện đại, mang đến trải nghiệm nghỉ dưỡng thoải mái và riêng tư.',0,900000,'Twin Room','2026-06-14 11:36:44.769876',1),(5,28,1,'DOUBLE',2,'2026-05-08 14:14:03.000000','Phòng Standard Double rộng 28m², được trang bị 1 giường đôi phù hợp cho 2 khách. Không gian sang trọng, rộng rãi với đầy đủ tiện nghi hiện đại, mang đến trải nghiệm nghỉ dưỡng thoải mái và riêng tư.',0,800000,'Standard Double Room','2026-06-14 11:38:45.385580',1),(6,20,1,'SINGLE',1,'2026-05-08 14:14:03.000000','Phòng Standard Single rộng 20m², được trang bị 1 giường đơn phù hợp cho 1 khách. Không gian sang trọng, rộng rãi với đầy đủ tiện nghi hiện đại, mang đến trải nghiệm nghỉ dưỡng thoải mái và riêng tư.',0,700000,'Standard Single Room','2026-06-14 11:40:24.362062',1),(7,60,1,'KING',2,'2026-05-08 14:14:03.000000','Phòng Suite rộng 60m², được trang bị 1 giường King cao cấp, phù hợp cho 2 khách. Không gi